import React from 'react';
import Slider from 'react-slick';
import './Works.css';

const Works = () => {
    const settings = {
        dots: true,
        infinite: true,
        speed: 500,
        slidesToShow: 1,
        slidesToScroll: 1,
        autoplay: true,
        autoplaySpeed: 3000,
        arrows: false
    };

    return (
        <section id="works">
            <h1>My Previous Projects</h1>
            <div className="carousel-container">
                <Slider {...settings}>
                    <div>
                        <img src="/img/project1.png" alt="Project 1" />
                    </div>
                    <div>
                        <img src="/img/project2.png" alt="Project 2" />
                    </div>
                    <div>
                        <img src="/img/project3.png" alt="Project 3" />
                    </div>
                    {/* Add more project images as needed */}
                </Slider>
            </div>
        </section>
    );
};

export default Works;
